Here's the result of running `cat -n` on a snippet of frontend/src/services/api.js
     1→import axios from 'axios';
     2→
     3→// In Replit, the CRA proxy (package.json "proxy") forwards /api/* to backend:8000
     4→// In local dev you can set REACT_APP_API_URL=http://localhost:8000/api
     5→const API_BASE_URL = process.env.REACT_APP_API_URL || '/api';
     6→
     7→const api = axios.create({
     8→  baseURL: API_BASE_URL,
     9→  headers: {
    10→    'Content-Type': 'application/json',
    11→  },
    12→});
    13→
    14→// Add token to requests
    15→api.interceptors.request.use((config) => {
    16→  const token = localStorage.getItem('access_token');
    17→  if (token) {
    18→    config.headers.Authorization = `Bearer ${token}`;
    19→  }
    20→  return config;
    21→});
    22→
    23→// Handle token refresh
    24→api.interceptors.response.use(
    25→  (response) => response,
    26→  async (error) => {
    27→    const originalRequest = error.config;
    28→
    29→    if (error.response?.status === 401 && !originalRequest._retry) {
    30→      originalRequest._retry = true;
    31→
    32→      try {
    33→        const refreshToken = localStorage.getItem('refresh_token');
    34→        const response = await axios.post(`${API_BASE_URL}/auth/refresh`, {}, {
    35→          headers: { Authorization: `Bearer ${refreshToken}` },
    36→        });
    37→
    38→        const { access_token } = response.data;
    39→        localStorage.setItem('access_token', access_token);
    40→
    41→        originalRequest.headers.Authorization = `Bearer ${access_token}`;
    42→        return api(originalRequest);
    43→      } catch (refreshError) {
    44→        localStorage.removeItem('access_token');
    45→        localStorage.removeItem('refresh_token');
    46→        window.location.href = '/login';
    47→        return Promise.reject(refreshError);
    48→      }
    49→    }
    50→
    51→    return Promise.reject(error);
    52→  }
    53→);
    54→
    55→export default api;
    56→

