await configureWorkflow({
    name: "Backend API",
    command: "cd backend && python run.py",
    waitForPort: 8000,
    outputType: "console"
});
console.log("Backend workflow configured");

await configureWorkflow({
    name: "Start application",
    command: "cd frontend && npm start",
    waitForPort: 5000,
    outputType: "webview"
});
