console.log("Frontend output:\n", frontend.output);

// This app uses WebSockets (Socket.IO) so it needs VM deployment (always-running)
// Production: build React frontend, then serve both via gunicorn+eventlet
const result = await deployConfig({
    deploymentTarget: "vm",
    build: ["bash", "-c", "cd frontend && npm run build"],
    run: ["bash", "-c", "cd backend && gunicorn --worker-class eventlet -w 1 --bind 0.0.0.0:5000 wsgi:app"]
});
console.log(result);

