import React, { useState, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FiX, FiSend, FiFile, FiMusic, FiVideo, FiImage, FiEdit2 } from 'react-icons/fi';

function formatBytes(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function FileTypeIcon({ file }) {
  const type = file.type;
  if (type.startsWith('image/')) return <FiImage size={40} className="text-purple-400" />;
  if (type.startsWith('video/')) return <FiVideo size={40} className="text-blue-400" />;
  if (type.startsWith('audio/')) return <FiMusic size={40} className="text-green-400" />;
  return <FiFile size={40} className="text-orange-400" />;
}

export default function AttachmentPreviewModal({ file, onSend, onCancel, uploading }) {
  const [caption, setCaption] = useState('');
  const inputRef = useRef(null);

  const isImage = file?.type?.startsWith('image/');
  const isVideo = file?.type?.startsWith('video/');
  const isAudio = file?.type?.startsWith('audio/');
  const objectUrl = file ? URL.createObjectURL(file) : null;

  const handleSend = useCallback(() => {
    if (!uploading) onSend(caption.trim());
  }, [caption, onSend, uploading]);

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
    if (e.key === 'Escape') onCancel();
  };

  if (!file) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 bg-black/90 flex flex-col items-center justify-center p-4"
        onClick={e => e.target === e.currentTarget && onCancel()}
      >
        <motion.div
          initial={{ scale: 0.92, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.92, opacity: 0 }}
          className="w-full max-w-lg flex flex-col bg-[#1a1a2e] rounded-2xl overflow-hidden shadow-2xl"
          onClick={e => e.stopPropagation()}
        >
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-3 border-b border-white/10">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-white/10 flex items-center justify-center">
                <FileTypeIcon file={file} />
              </div>
              <div className="min-w-0">
                <p className="text-white text-sm font-semibold truncate max-w-[200px]">{file.name}</p>
                <p className="text-white/40 text-xs">{formatBytes(file.size)}</p>
              </div>
            </div>
            <button onClick={onCancel} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white/10 text-white/60 hover:text-white transition">
              <FiX size={18} />
            </button>
          </div>

          {/* Preview area */}
          <div className="flex-1 flex items-center justify-center p-6 min-h-[260px] bg-black/30">
            {isImage && objectUrl && (
              <img src={objectUrl} alt="preview" className="max-w-full max-h-[300px] rounded-xl object-contain shadow-xl" />
            )}
            {isVideo && objectUrl && (
              <video src={objectUrl} controls className="max-w-full max-h-[300px] rounded-xl shadow-xl" />
            )}
            {isAudio && objectUrl && (
              <div className="w-full flex flex-col items-center gap-4">
                <div className="w-20 h-20 rounded-full bg-gradient-to-br from-green-400 to-teal-500 flex items-center justify-center shadow-xl">
                  <FiMusic size={36} className="text-white" />
                </div>
                <audio src={objectUrl} controls className="w-full" style={{ filter: 'invert(0.8) hue-rotate(170deg)' }} />
              </div>
            )}
            {!isImage && !isVideo && !isAudio && (
              <div className="flex flex-col items-center gap-4 text-center">
                <div className="w-24 h-24 rounded-2xl bg-white/10 flex items-center justify-center">
                  <FileTypeIcon file={file} />
                </div>
                <div>
                  <p className="text-white font-semibold text-base truncate max-w-[260px]">{file.name}</p>
                  <p className="text-white/50 text-sm mt-1">{formatBytes(file.size)}</p>
                  <p className="text-white/30 text-xs mt-0.5">{file.type || 'Unknown type'}</p>
                </div>
              </div>
            )}
          </div>

          {/* Caption input */}
          <div className="px-4 py-3 border-t border-white/10">
            <div className="flex items-end gap-3">
              <div className="flex-1 bg-white/10 rounded-2xl px-4 py-2.5 flex items-start gap-2">
                <FiEdit2 size={14} className="text-white/40 mt-0.5 flex-shrink-0" />
                <textarea
                  ref={inputRef}
                  value={caption}
                  onChange={e => setCaption(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Add a caption..."
                  rows={1}
                  className="flex-1 bg-transparent text-white text-sm outline-none resize-none placeholder-white/30 leading-5"
                  style={{ height: 'auto' }}
                  onInput={e => { e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 80) + 'px'; }}
                  autoFocus
                />
              </div>
              <button
                onClick={handleSend}
                disabled={uploading}
                className="w-11 h-11 bg-[#25D366] hover:bg-[#1fbd5a] disabled:opacity-50 text-white rounded-full flex items-center justify-center flex-shrink-0 shadow-lg transition"
              >
                {uploading
                  ? <motion.div animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: 'linear' }} className="w-5 h-5 border-2 border-white border-t-transparent rounded-full" />
                  : <FiSend size={18} />
                }
              </button>
            </div>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}

import { useRef, useCallback, useState } from 'react';
import { getSocket } from '../services/socket';
import api from '../services/api';

const ICE_SERVERS = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun2.l.google.com:19302' },
    { urls: 'stun:stun4.l.google.com:19302' },
    { urls: 'turn:openrelay.metered.ca:80', username: 'openrelayproject', credential: 'openrelayproject' },
    { urls: 'turn:openrelay.metered.ca:443', username: 'openrelayproject', credential: 'openrelayproject' },
  ],
  iceCandidatePoolSize: 10,
};

export function useGroupWebRTC(currentUser) {
  const peerConnectionsRef = useRef({});
  const localStreamRef = useRef(null);
  const [localStream, setLocalStream] = useState(null);
  const [remoteStreams, setRemoteStreams] = useState({});
  const [participants, setParticipants] = useState([]);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(false);
  const [callActive, setCallActive] = useState(false);
  const [groupCallId, setGroupCallId] = useState(null);

  const getLocalStream = useCallback(async (callType = 'video') => {
    const constraints = {
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      video: callType === 'video' ? { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'user' } : false,
    };
    try {
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      localStreamRef.current = stream;
      setLocalStream(stream);
      return stream;
    } catch {
      if (callType === 'video') {
        const fallback = await navigator.mediaDevices.getUserMedia({ audio: constraints.audio });
        localStreamRef.current = fallback;
        setLocalStream(fallback);
        return fallback;
      }
      throw new Error('Could not access media devices');
    }
  }, []);

  const createPeerConnection = useCallback((targetUserId, stream) => {
    const pc = new RTCPeerConnection(ICE_SERVERS);

    stream?.getTracks().forEach(track => pc.addTrack(track, stream));

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        const socket = getSocket();
        socket?.emit('group_ice_candidate', {
          from_user_id: currentUser.id,
          target_user_id: targetUserId,
          call_id: groupCallId,
          candidate: event.candidate,
        });
      }
    };

    pc.ontrack = (event) => {
      if (event.streams?.[0]) {
        setRemoteStreams(prev => ({ ...prev, [targetUserId]: event.streams[0] }));
      }
    };

    pc.onconnectionstatechange = () => {
      if (pc.connectionState === 'disconnected' || pc.connectionState === 'failed') {
        setRemoteStreams(prev => {
          const next = { ...prev };
          delete next[targetUserId];
          return next;
        });
      }
    };

    peerConnectionsRef.current[targetUserId] = pc;
    return pc;
  }, [currentUser?.id, groupCallId]);

  const sendOfferTo = useCallback(async (targetUserId, stream, callType, callId) => {
    const pc = createPeerConnection(targetUserId, stream);
    const offer = await pc.createOffer({ offerToReceiveAudio: true, offerToReceiveVideo: callType === 'video' });
    await pc.setLocalDescription(offer);
    const socket = getSocket();
    socket?.emit('group_call_offer', {
      from_user_id: currentUser.id,
      from_user_name: currentUser.full_name,
      target_user_id: targetUserId,
      call_id: callId,
      call_type: callType,
      offer,
    });
  }, [createPeerConnection, currentUser]);

  const initiateGroupCall = useCallback(async (groupId, groupName, callType = 'video') => {
    try {
      const callId = `gc_${Date.now()}_${Math.random().toString(36).slice(2)}`;
      setGroupCallId(callId);
      const stream = await getLocalStream(callType);
      setCallActive(true);

      const socket = getSocket();
      socket?.emit('group_call_start', {
        group_id: groupId,
        initiator_id: currentUser.id,
        initiator_name: currentUser.full_name,
        initiator_avatar: currentUser.avatar_url,
        call_type: callType,
        call_id: callId,
        group_name: groupName,
      });
      socket?.emit('group_call_join', { call_id: callId, user_id: currentUser.id, user_name: currentUser.full_name });

      // Log call in backend
      api.post('/calls/initiate', { receiver_id: null, call_type: callType, group_id: groupId }).catch(() => {});

      return callId;
    } catch (err) {
      console.error('[GroupWebRTC] initiateGroupCall error:', err);
      cleanupGroupCall();
      throw err;
    }
  }, [currentUser, getLocalStream]);

  const joinGroupCall = useCallback(async (callId, callType, existingParticipants) => {
    try {
      setGroupCallId(callId);
      const stream = await getLocalStream(callType);
      setCallActive(true);

      const socket = getSocket();
      socket?.emit('group_call_join', { call_id: callId, user_id: currentUser.id, user_name: currentUser.full_name });

      for (const p of (existingParticipants || [])) {
        if (p.user_id !== currentUser.id) {
          await sendOfferTo(p.user_id, stream, callType, callId);
        }
      }
    } catch (err) {
      console.error('[GroupWebRTC] joinGroupCall error:', err);
      cleanupGroupCall();
      throw err;
    }
  }, [currentUser, getLocalStream, sendOfferTo]);

  const handleGroupOffer = useCallback(async (data) => {
    const { from_user_id, call_id, call_type, offer } = data;
    const stream = localStreamRef.current;
    if (!stream) return;

    const pc = createPeerConnection(from_user_id, stream);
    await pc.setRemoteDescription(new RTCSessionDescription(offer));
    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);

    const socket = getSocket();
    socket?.emit('group_call_answer', {
      from_user_id: currentUser.id,
      target_user_id: from_user_id,
      call_id,
      answer,
    });
  }, [createPeerConnection, currentUser?.id]);

  const handleGroupAnswer = useCallback(async (data) => {
    const { from_user_id, answer } = data;
    const pc = peerConnectionsRef.current[from_user_id];
    if (pc && pc.signalingState === 'have-local-offer') {
      await pc.setRemoteDescription(new RTCSessionDescription(answer));
    }
  }, []);

  const handleGroupIce = useCallback(async (data) => {
    const { from_user_id, candidate } = data;
    const pc = peerConnectionsRef.current[from_user_id];
    if (pc && candidate) {
      try { await pc.addIceCandidate(new RTCIceCandidate(candidate)); } catch {}
    }
  }, []);

  const handleUserJoined = useCallback((data) => {
    setParticipants(prev => {
      if (prev.find(p => p.user_id === data.user_id)) return prev;
      return [...prev, { user_id: data.user_id, user_name: data.user_name }];
    });
  }, []);

  const handleUserLeft = useCallback((data) => {
    const { user_id } = data;
    const pc = peerConnectionsRef.current[user_id];
    if (pc) { pc.close(); delete peerConnectionsRef.current[user_id]; }
    setRemoteStreams(prev => { const n = { ...prev }; delete n[user_id]; return n; });
    setParticipants(prev => prev.filter(p => p.user_id !== user_id));
  }, []);

  const toggleMute = useCallback(() => {
    const stream = localStreamRef.current;
    if (!stream) return;
    stream.getAudioTracks().forEach(t => { t.enabled = !t.enabled; });
    setIsMuted(m => !m);
  }, []);

  const toggleCamera = useCallback(() => {
    const stream = localStreamRef.current;
    if (!stream) return;
    stream.getVideoTracks().forEach(t => { t.enabled = !t.enabled; });
    setIsCameraOff(v => !v);
  }, []);

  const cleanupGroupCall = useCallback(() => {
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach(t => t.stop());
      localStreamRef.current = null;
    }
    Object.values(peerConnectionsRef.current).forEach(pc => pc.close());
    peerConnectionsRef.current = {};
    setLocalStream(null);
    setRemoteStreams({});
    setParticipants([]);
    setCallActive(false);
    setGroupCallId(null);
    setIsMuted(false);
    setIsCameraOff(false);
  }, []);

  const leaveGroupCall = useCallback((callId) => {
    const socket = getSocket();
    socket?.emit('group_call_leave', { call_id: callId || groupCallId, user_id: currentUser.id });
    cleanupGroupCall();
  }, [currentUser?.id, groupCallId, cleanupGroupCall]);

  return {
    localStream,
    remoteStreams,
    participants,
    isMuted,
    isCameraOff,
    callActive,
    groupCallId,
    initiateGroupCall,
    joinGroupCall,
    handleGroupOffer,
    handleGroupAnswer,
    handleGroupIce,
    handleUserJoined,
    handleUserLeft,
    toggleMute,
    toggleCamera,
    leaveGroupCall,
    cleanupGroupCall,
  };
}

import React, { useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  FiMic, FiMicOff, FiVideo, FiVideoOff, FiPhoneOff,
  FiUsers, FiMinimize2, FiMaximize2,
} from 'react-icons/fi';

function VideoTile({ stream, label, isLocal, isMuted, isCameraOff }) {
  const videoRef = useRef(null);

  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
    }
  }, [stream]);

  const initial = label?.[0]?.toUpperCase() || '?';

  return (
    <div className="relative bg-gray-900 rounded-2xl overflow-hidden flex items-center justify-center aspect-video">
      {stream && !isCameraOff ? (
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted={isLocal}
          className="w-full h-full object-cover"
        />
      ) : (
        <div className="flex flex-col items-center gap-2">
          <div className="w-16 h-16 rounded-full bg-gradient-to-br from-green-400 to-teal-500 flex items-center justify-center text-white font-bold text-2xl">
            {initial}
          </div>
          <p className="text-white/60 text-xs">{isCameraOff ? 'Camera off' : 'No video'}</p>
        </div>
      )}
      {/* Name tag */}
      <div className="absolute bottom-2 left-2 flex items-center gap-1.5 bg-black/50 rounded-full px-2 py-1">
        {isMuted && <FiMicOff size={10} className="text-red-400" />}
        <span className="text-white text-xs font-medium">{isLocal ? `${label} (You)` : label}</span>
      </div>
    </div>
  );
}

export default function GroupCallScreen({
  localStream,
  remoteStreams,
  participants,
  groupName,
  callType,
  isMuted,
  isCameraOff,
  onToggleMute,
  onToggleCamera,
  onLeave,
  callDuration,
}) {
  const [minimized, setMinimized] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const controlsTimer = useRef(null);

  const resetTimer = () => {
    setShowControls(true);
    clearTimeout(controlsTimer.current);
    controlsTimer.current = setTimeout(() => setShowControls(false), 4000);
  };

  useEffect(() => {
    if (callType === 'video') resetTimer();
    return () => clearTimeout(controlsTimer.current);
  }, [callType]);

  const formatDuration = (s) => {
    if (!s) return '00:00';
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
  };

  const remoteEntries = Object.entries(remoteStreams);
  const totalTiles = 1 + remoteEntries.length;

  const gridClass = totalTiles === 1 ? 'grid-cols-1' :
    totalTiles === 2 ? 'grid-cols-2' :
    totalTiles <= 4 ? 'grid-cols-2' :
    'grid-cols-3';

  if (minimized) {
    return (
      <motion.div
        initial={{ scale: 0.8, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        className="fixed bottom-24 right-4 z-50 w-52 bg-gray-900 rounded-2xl overflow-hidden shadow-2xl border border-white/10 cursor-pointer"
        onClick={() => setMinimized(false)}
      >
        <div className="aspect-video bg-gray-800 flex items-center justify-center relative">
          {localStream && callType === 'video' && !isCameraOff ? (
            <video autoPlay playsInline muted className="w-full h-full object-cover" ref={el => { if (el) el.srcObject = localStream; }} />
          ) : (
            <FiUsers size={28} className="text-white/40" />
          )}
          <div className="absolute inset-0 bg-black/30 flex items-end justify-between p-2">
            <span className="text-white text-xs font-medium truncate">{groupName}</span>
            <span className="text-[#25D366] text-xs font-mono">{formatDuration(callDuration)}</span>
          </div>
        </div>
        <div className="flex justify-around py-2 px-2">
          <button onClick={e => { e.stopPropagation(); onToggleMute(); }} className={`p-2 rounded-full ${isMuted ? 'bg-red-500' : 'bg-white/10'}`}>
            {isMuted ? <FiMicOff size={14} className="text-white" /> : <FiMic size={14} className="text-white" />}
          </button>
          <button onClick={e => { e.stopPropagation(); onLeave(); }} className="p-2 rounded-full bg-red-500">
            <FiPhoneOff size={14} className="text-white" />
          </button>
          <button onClick={e => { e.stopPropagation(); setMinimized(false); }} className="p-2 rounded-full bg-white/10">
            <FiMaximize2 size={14} className="text-white" />
          </button>
        </div>
      </motion.div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 bg-[#0d1117] flex flex-col"
      onMouseMove={callType === 'video' ? resetTimer : undefined}
      onClick={callType === 'video' ? resetTimer : undefined}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 pt-10 pb-4">
        <div>
          <h2 className="text-white font-bold text-lg">{groupName || 'Group Call'}</h2>
          <p className="text-[#25D366] text-sm font-mono">{formatDuration(callDuration)} · {totalTiles} participant{totalTiles !== 1 ? 's' : ''}</p>
        </div>
        <button onClick={() => setMinimized(true)} className="w-9 h-9 flex items-center justify-center rounded-full bg-white/10 hover:bg-white/20 text-white transition">
          <FiMinimize2 size={16} />
        </button>
      </div>

      {/* Video grid */}
      <div className={`flex-1 grid ${gridClass} gap-2 px-4 pb-4 overflow-hidden`} style={{ alignContent: 'start' }}>
        <VideoTile
          stream={localStream}
          label="You"
          isLocal
